<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,watch,nextTick} from 'vue';
import FocusSettings from './FocusSettings.vue';import FocusReports from './FocusReports.vue';import {focusApi,duration,localDate} from './api';import {noise,stopNoise,alarm} from './audio';import {connectFocus} from './realtime';import './focus.css';
defineProps<{csrf?:string|null}>();
const data=ref<any>(null),section=ref('Today'),search=ref(''),title=ref(''),loading=ref(true),busy=ref(false),toast=ref(''),error=ref(''),editor=ref<any>(null),dialog=ref<HTMLDialogElement|null>(null),kind=ref('task'),projectId=ref<number|null>(null),taskPage=ref(1),selectedTask=ref(''),timerMode=ref('countdown'),now=ref(Date.now()),offset=ref(0),bell=ref(false),live=ref('connecting'),lastSync=ref(''),social=ref<any>({groups:[],rankings:[]}),socialCompany=ref(''),socialPeriod=ref('month'),socialSearch=ref(''),groupMode=ref('mine'),groupDetails=ref<any>(null),timerBox=ref<HTMLElement|null>(null);
let reloadPending=false;let interval:number|undefined,toastTimer:number|undefined,disconnect:(()=>void)|undefined,syncing=false,deadline:number|null=null,disposed=false;
function message(text:string){toast.value=text;clearTimeout(toastTimer);toastTimer=window.setTimeout(()=>toast.value='',4500);}
async function run(fn:()=>Promise<void>,success=''){if(busy.value)return;busy.value=true;error.value='';try{await fn();if(success)message(success);}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
async function load(){if(syncing){reloadPending=true;return;}syncing=true;try{const next=await focusApi('data');if(disposed)return;const oldIds=new Set(data.value?.notifications.map((n:any)=>n.id)||[]);if(data.value&&'Notification'in window&&Notification.permission==='granted'){for(const n of next.notifications.filter((n:any)=>!n.read_at&&!oldIds.has(n.id)))new Notification('Focus To Do',{body:n.title});}data.value=next;offset.value=Date.parse(next.server_now)-Date.now();lastSync.value=new Date().toLocaleTimeString();if(!socialCompany.value&&next.companies.length)socialCompany.value=String(next.companies[0].id);if(!selectedTask.value&&next.tasks.find((t:any)=>!t.completed_at))selectedTask.value=String(next.tasks.find((t:any)=>!t.completed_at).id);error.value='';}catch(e:any){error.value=e.message;}finally{loading.value=false;syncing=false;if(reloadPending&&!disposed){reloadPending=false;void load();}}}
const active=computed(()=>data.value?.timer),elapsed=computed(()=>active.value?Number(active.value.elapsed_seconds)+(active.value.status==='running'?Math.min(Math.max(0,Math.floor((now.value+offset.value-Date.parse(active.value.segment_started_at))/1000)),active.value.target_seconds-active.value.elapsed_seconds):0):0);
const clock=computed(()=>{const value=active.value?active.value.mode==='stopwatch'?elapsed.value:Math.max(0,active.value.target_seconds-elapsed.value):(data.value?.settings.focus_minutes||25)*60;return `${String(Math.floor(value/60)).padStart(2,'0')}:${String(Math.floor(value%60)).padStart(2,'0')}`;});
const progress=computed(()=>active.value?Math.min(100,elapsed.value/active.value.target_seconds*100):0),projects=computed(()=>data.value?.projects.filter((p:any)=>!p.is_folder)||[]),folders=computed(()=>data.value?.projects.filter((p:any)=>p.is_folder)||[]);
const navigation=computed(()=>['Today','Tasks',...(data.value?.settings.lists||[]),'Timer','Reports',...(data.value?.settings.groups?['Groups']:[]),...(data.value?.settings.forest?['Forest']:[]),...(data.value?.settings.ranking?['Ranking']:[]),'Settings']);
const utility=['Timer','Reports','Groups','Forest','Ranking','Settings'];
function select(name:string,id:number|null=null){section.value=name;projectId.value=id;taskPage.value=1;search.value='';if(['Groups','Ranking'].includes(name))void loadSocial();}
function matchesList(t:any,name:string){const today=data.value?.today||localDate(),date=t.due_date;if(name==='Completed')return !!t.completed_at;if(t.completed_at)return false;
 switch(name){case 'Today':return date===today;case 'Tasks':return !t.project_id;case 'Tomorrow':{const d=new Date(today+'T12:00:00');d.setDate(d.getDate()+1);return date===localDate(d);}case 'This week':{const d=new Date(today+'T12:00:00');d.setDate(d.getDate()+7-((d.getDay()+6)%7)-1);return date&&date>=today&&date<=localDate(d);}case 'Next 7 days':{const d=new Date(today+'T12:00:00');d.setDate(d.getDate()+6);return date&&date>=today&&date<=localDate(d);}case 'Planned':return !!date;case 'Someday':return !date;case 'Overdue':return date&&date<today;case 'Events':return !!t.remind_at;case 'High priority':return t.priority==='high';case 'Medium priority':return t.priority==='medium';case 'Low priority':return t.priority==='low';default:return true;}}
const filtered=computed(()=>data.value?.tasks.filter((t:any)=>(projectId.value?t.project_id===projectId.value&&!t.completed_at:matchesList(t,section.value))&&[t.title,t.notes,...t.tags].join(' ').toLowerCase().includes(search.value.toLowerCase()))||[]),pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/10))),visible=computed(()=>filtered.value.slice((taskPage.value-1)*10,taskPage.value*10));
watch(search,()=>taskPage.value=1);watch(pages,n=>taskPage.value=Math.min(taskPage.value,n));
function estimateList(name:string,id?:number){const tasks=data.value?.tasks.filter((t:any)=>id?t.project_id===id&&!t.completed_at:matchesList(t,name)&&!t.completed_at)||[];return duration(tasks.reduce((n:number,t:any)=>n+t.estimate*(data.value?.settings.focus_minutes||25)*60,0));}
function count(name:string,id?:number){return data.value?.tasks.filter((t:any)=>id?t.project_id===id&&!t.completed_at:matchesList(t,name)).length||0;}
const estimates=computed(()=>filtered.value.filter((t:any)=>!t.completed_at).reduce((sum:number,t:any)=>sum+t.estimate*data.value.settings.focus_minutes*60,0));
const blankTask=()=>({title:'',notes:'',project_id:projectId.value,priority:'none',estimate:1,due_date:section.value==='Today'?data.value.today:null,remind_at:null,repeat:'none',tags:[],subtasks:[]});
async function open(type:string,item?:any){kind.value=type;groupDetails.value=null;
 editor.value=type==='task'?(item?JSON.parse(JSON.stringify(item)):blankTask()):type==='project'||type==='folder'?{name:'',color:'#7762ee',folder_id:null,is_folder:type==='folder',...(item||{})}:type==='manual'?{task_id:selectedTask.value,started_at:'',minutes:25,...(item?{id:item.id,task_id:item.task_id,started_at:localInput(item.started_at),minutes:Math.round(item.elapsed_seconds/60)}:{})}:type==='group'?{name:'',description:''}:{confirmation:''};
 if(type==='task'){editor.value.tagText=editor.value.tags.join(', ');editor.value.remindLocal=editor.value.remind_at?localInput(editor.value.remind_at):'';}
 await nextTick();dialog.value?.showModal();}
function localInput(value:string){const d=new Date(value);return `${localDate(d)}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;}
function close(){dialog.value?.close();editor.value=null;}
async function save(){await run(async()=>{const e=editor.value;if(kind.value==='task')await focusApi('tasks'+(e.id?'/'+e.id:''),'POST',{...e,tags:e.tagText.split(',').map((s:string)=>s.trim()).filter(Boolean),remind_at:e.remindLocal?new Date(e.remindLocal).toISOString():null});
 else if(['project','folder'].includes(kind.value))await focusApi('projects'+(e.id?'/'+e.id:''),'POST',e);
 else if(kind.value==='manual')await focusApi('manual'+(e.id?'/'+e.id:''),'POST',{...e,started_at:new Date(e.started_at).toISOString()});
 else if(kind.value==='group'){await focusApi('groups','POST',{...e,company_id:Number(socialCompany.value),action:'create'});await loadSocial();}
 else if(kind.value==='clear'){await focusApi('clear','POST',e);select('Today');}
 close();await load();},'Saved successfully.');}
async function addTask(){if(!title.value.trim())return;await run(async()=>{await focusApi('tasks','POST',{...blankTask(),title:title.value.trim()});title.value='';await load();},'Task added.');}
async function complete(task:any){await run(async()=>{await focusApi(`tasks/${task.id}/complete`,'POST',{completed:!task.completed_at});if(!task.completed_at&&data.value.settings.completion_sound)alarm(20,'chime');await load();},task.completed_at?'Task reopened.':'Task completed.');}
async function removeTask(){if(!confirm('Delete this task? Its recorded focus time is retained.'))return;await run(async()=>{await focusApi('tasks/'+editor.value.id,'DELETE');close();await load();},'Task deleted.');}
async function removeProject(){if(!confirm('Delete this project/folder? Tasks move to Tasks; focus records stay available.'))return;await run(async()=>{await focusApi('projects/'+editor.value.id,'DELETE');close();select('Tasks');await load();},'Project deleted.');}
async function timer(action:string){await run(async()=>{const result=await focusApi('timer','POST',{action,task_id:Number(selectedTask.value),session_id:active.value?.id,mode:timerMode.value});data.value.timer=result.timer;offset.value=Date.parse(result.server_now)-Date.now();if(action==='start'||action==='resume')noise(data.value.settings.noise,data.value.settings.noise_volume);else stopNoise();await load();});}
function focusTask(task:any){selectedTask.value=String(task.id);select('Timer');}
async function loadSocial(){if(!socialCompany.value)return;try{social.value=await focusApi(`social?company_id=${socialCompany.value}&period=${socialPeriod.value}`);}catch(e:any){error.value=e.message;}}
watch([socialCompany,socialPeriod],loadSocial);
async function group(action:string,g:any){await run(async()=>{await focusApi('groups','POST',{action,id:g.id,company_id:Number(socialCompany.value)});await loadSocial();},'Group updated.');}
const groups=computed(()=>social.value.groups.filter((g:any)=>(groupMode.value==='discover'||g.mine)&&[g.name,g.description].join(' ').toLowerCase().includes(socialSearch.value.toLowerCase()))),pending=computed(()=>data.value?.pending_sunlight??(data.value?.rewards.filter((r:any)=>!r.collected_at&&r.grams>0).reduce((n:number,r:any)=>n+r.grams,0)||0)),level=computed(()=>Math.floor((data.value?.sunlight||0)/600));
async function readNotifications(task?:any){await run(async()=>{await focusApi('notifications','POST',task?{id:task.id}:{});await load();if(task?.task_id){const found=data.value.tasks.find((t:any)=>t.id===task.task_id);if(found)await open('task',found);}});}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await timerBox.value?.requestFullscreen();}catch{message('Fullscreen is unavailable in this browser.');}}
async function enableNotifications(){if('Notification'in window){const result=await Notification.requestPermission();message(result==='granted'?'Browser notifications enabled while this workspace is open.':'Browser notifications were not enabled.');}}
function outside(event:PointerEvent){if(!(event.target as HTMLElement)?.closest('.ft-bell'))bell.value=false;}
function escape(event:KeyboardEvent){if(event.key==='Escape')bell.value=false;}
function visibility(){if(document.visibilityState==='visible')void load();}
onMounted(async()=>{await load();disconnect=connectFocus(()=>document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content||'',()=>{if(!busy.value){void load();if(['Groups','Ranking'].includes(section.value))void loadSocial();}},state=>live.value=state,()=>{void load();});interval=window.setInterval(async()=>{now.value=Date.now();if(active.value?.status==='running'&&elapsed.value>=active.value.target_seconds&&deadline!==active.value.id){deadline=active.value.id;stopNoise();alarm(data.value.settings.alarm_volume,active.value.phase==='focus'?data.value.settings.alarm:(data.value.settings.break_alarm||'chime'));await timer('sync');deadline=null;}},1000);document.addEventListener('visibilitychange',visibility);document.addEventListener('pointerdown',outside);document.addEventListener('keydown',escape);});
onBeforeUnmount(()=>{disposed=true;clearInterval(interval);clearTimeout(toastTimer);disconnect?.();stopNoise();document.removeEventListener('visibilitychange',visibility);document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',escape);});
</script>
<template><main class="ft-workspace" :class="'ft-bg-'+(data?.settings.background||'plain')"><header class="ft-page-header"><div><p class="ft-eyebrow">JUDIBAS / PERSONAL PRODUCTIVITY</p><h1>Focus To Do</h1><p class="ft-muted">Make room for your most important work.</p></div><div class="ft-header-tools"><span class="ft-sync" :title="'Last synced: '+lastSync">{{live==='live'?'● Live sync':'Sync: '+live}}</span><button :disabled="busy" @click="load">Sync now</button><div class="ft-bell"><button aria-label="Notifications" @click="bell=!bell">Notifications <span v-if="data?.notifications.filter((n:any)=>!n.read_at).length" class="ft-badge">{{data.notifications.filter((n:any)=>!n.read_at).length}}</span></button><section v-if="bell" class="ft-notifications"><div class="ft-heading"><strong>Notifications</strong><button aria-label="Close notifications" @click="bell=false">×</button></div><button @click="readNotifications()">Mark all read</button><button @click="enableNotifications">Enable browser alerts</button><div class="ft-notification-list"><button v-for="n in data?.notifications" :class="{unread:!n.read_at}" @click="readNotifications(n)"><strong>{{n.title}}</strong><small>{{new Date(n.created_at).toLocaleString()}}</small></button><p v-if="!data?.notifications.length" class="ft-empty">You’re all caught up.</p></div></section></div></div></header>
<div v-if="toast" class="ft-toast" role="status">✓ {{toast}}</div><div v-if="error" class="ft-error" role="alert">{{error}}<button aria-label="Dismiss error" @click="error=''">×</button></div><p v-if="loading" class="ft-empty">Loading your workspace…</p>
<div v-else-if="data" class="ft-layout"><aside class="ft-sidebar"><p class="ft-eyebrow">YOUR WORKSPACE</p><button v-for="name in navigation" :class="{active:section===name&&!projectId}" @click="select(name)"><span>{{name}}</span><small v-if="!utility.includes(name)">{{count(name)}}<span class="ft-nav-time">{{estimateList(name)}}</span></small></button><div class="ft-heading ft-sidebar-heading"><p class="ft-eyebrow">PROJECTS</p><button aria-label="Create project" @click="open('project')">+</button></div><button v-for="p in projects.filter((p:any)=>!p.folder_id)" :class="{active:projectId===p.id}" @click="select(p.name,p.id)"><span><i :style="{background:p.color}"></i>{{p.name}}</span><small>{{count('',p.id)}}<span class="ft-nav-time">{{estimateList('',p.id)}}</span></small></button><details v-for="f in folders" class="ft-folder"><summary>{{f.name}}<button aria-label="Edit folder" @click.prevent="open('folder',f)">⋯</button></summary><button v-for="p in projects.filter((p:any)=>p.folder_id===f.id)" :class="{active:projectId===p.id}" @click="select(p.name,p.id)"><span><i :style="{background:p.color}"></i>{{p.name}}</span><small>{{count('',p.id)}}<span class="ft-nav-time">{{estimateList('',p.id)}}</span></small></button></details><button class="ft-muted" @click="open('folder')">+ New folder</button><a href="/products">← All products</a></aside>
<section class="ft-content"><header class="ft-section-header"><div><p class="ft-eyebrow">{{utility.includes(section)?'FOCUS WORKSPACE':'YOUR TASKS'}}</p><h2>{{section}}</h2></div><button v-if="projectId" @click="open('project',projects.find((p:any)=>p.id===projectId))">Edit project</button><input v-if="!utility.includes(section)" v-model="search" type="search" placeholder="Search tasks, tags or notes…" aria-label="Search tasks"></header>
<template v-if="!utility.includes(section)"><div class="ft-stats"><article><small>Estimated time</small><strong>{{duration(estimates)}}</strong></article><article><small>Tasks to complete</small><strong>{{filtered.filter((t:any)=>!t.completed_at).length}}</strong></article><article><small>Focused today</small><strong>{{duration(data.summary.seconds)}}</strong></article><article><small>Completed today</small><strong>{{data.summary.completed}}</strong></article></div><article class="ft-panel ft-task-panel"><form v-if="section!=='Completed'" class="ft-add" @submit.prevent="addTask"><span>+</span><input v-model="title" placeholder="Add a task and press Enter" aria-label="New task" maxlength="250" required><button class="ft-primary" :disabled="busy">Add task</button></form><div v-for="task in visible" :key="task.id" class="ft-task-row"><input type="checkbox" :checked="!!task.completed_at" :disabled="busy" aria-label="Complete task" @change="complete(task)"><button class="ft-task-title" :class="{done:task.completed_at}" @click="open('task',task)"><strong>{{task.title}}</strong><small><span v-if="task.project_id">{{projects.find((p:any)=>p.id===task.project_id)?.name}} · </span>{{task.due_date||'No due date'}}<span v-if="task.repeat!=='none'"> · Repeats {{task.repeat}}</span><span v-if="task.tags.length"> · {{task.tags.map((t:string)=>'#'+t).join(' ')}}</span></small></button><span class="ft-priority" :class="task.priority">{{task.priority==='none'?'':task.priority}}</span><small class="ft-estimate">{{task.estimate}} sessions</small><button v-if="!task.completed_at" title="Focus on this task" @click="focusTask(task)">▷ Focus</button><button aria-label="Edit task" @click="open('task',task)">⋯</button></div><div v-if="!filtered.length" class="ft-empty"><div class="ft-empty-icon">✓</div><h3>A little space to focus</h3><p>{{section==='Completed'?'Your finished tasks will appear here.':'Add a task or choose another list to get started.'}}</p></div><footer class="ft-pagination"><small>{{filtered.length}} tasks · Page {{taskPage}} of {{pages}}</small><div><button :disabled="taskPage===1" @click="taskPage--">Previous</button><button :disabled="taskPage===pages" @click="taskPage++">Next</button></div></footer></article></template>
<template v-else-if="section==='Timer'"><div ref="timerBox" class="ft-focus-stage"><div class="ft-heading"><span class="ft-pill">{{active?active.phase==='focus'?'Focus time':active.phase==='long'?'Long break':'Short break':'Ready to focus'}}</span><button @click="fullscreen">Full screen</button></div><select v-model="selectedTask" :disabled="!!active"><option value="">Select a task</option><option v-for="t in data.tasks.filter((t:any)=>!t.completed_at)" :value="String(t.id)">{{t.title}}</option></select><h3 v-if="active">{{active.task_title||'Focus session'}}</h3><div class="ft-clock" :style="{'--progress':progress+'%'}"><span>{{clock}}</span><small>{{active?.status||'One task. Your full attention.'}}</small></div><div class="ft-timer-actions"><template v-if="!active"><select v-model="timerMode"><option value="countdown">Pomodoro</option><option value="stopwatch">Stopwatch</option></select><button class="ft-primary" :disabled="busy||!selectedTask" @click="timer('start')">Start focus</button></template><template v-else><button class="ft-primary" :disabled="busy" @click="timer(active.status==='running'?'pause':'resume')">{{active.status==='running'?'Pause':'Start / resume'}}</button><button :disabled="busy" @click="timer('stop')">{{active.phase==='focus'?'Finish session':'Skip break'}}</button><button :disabled="busy" @click="timer('reset')">Reset</button></template></div><p class="ft-muted">{{data.settings.focus_minutes}} min focus · {{data.settings.short_break}} min short break · {{data.settings.long_break}} min long break</p><button @click="noise(data.settings.noise,data.settings.noise_volume)">Play selected ambience</button><button @click="stopNoise">Mute</button></div><article class="ft-panel"><h3>Today’s rhythm</h3><p class="ft-muted">{{duration(data.summary.seconds)}} focused · {{data.summary.completed}} tasks completed</p><div v-for="s in data.sessions.filter((s:any)=>localDate(new Date(s.started_at))===data.today).slice(0,12)" class="ft-report-row"><span>{{s.task_title||'Session'}} <small class="ft-muted">· {{s.phase}} · {{s.status}}</small></span><strong>{{duration(s.elapsed_seconds)}}</strong></div></article></template>
<FocusReports v-else-if="section==='Reports'" :data="data" @manual="record=>open('manual',record)"/>
<template v-else-if="section==='Groups'||section==='Ranking'"><div class="ft-toolbar"><label>Company<select v-model="socialCompany"><option v-for="c in data.companies" :value="String(c.id)">{{c.name}}</option></select></label><label>Period<select v-model="socialPeriod"><option value="month">Last 30 days</option><option value="overall">Overall</option></select></label><button @click="loadSocial">Refresh</button><button v-if="section==='Groups'&&socialCompany" class="ft-primary" @click="open('group')">+ Create group</button></div><p class="ft-muted">Only active Focus users in this company are included. Personal tasks and notes remain private. Manual records do not affect rankings.</p><p v-if="!socialCompany" class="ft-empty">Ask your administrator to assign a company to use groups and rankings.</p><template v-else-if="section==='Groups'"><div class="ft-toolbar"><div class="ft-tabs"><button :class="{active:groupMode==='mine'}" @click="groupMode='mine'">My groups</button><button :class="{active:groupMode==='discover'}" @click="groupMode='discover'">Discover</button></div><input v-model="socialSearch" placeholder="Find a group…"></div><div class="ft-card-grid"><article v-for="g in groups" class="ft-panel"><span class="ft-empty-icon">◎</span><h3>{{g.name}}</h3><p class="ft-muted">{{g.description}}</p><p>{{g.members.length}} members · {{duration(g.seconds)}}</p><div class="ft-actions"><button @click="groupDetails=groupDetails?.id===g.id?null:g">Members</button><button :disabled="busy" @click="group(g.mine?'leave':'join',g)">{{g.mine?'Leave':'Join group'}}</button><button v-if="g.owned" :disabled="busy" @click="group('delete',g)">Delete</button></div><div v-if="groupDetails?.id===g.id" class="ft-members"><p v-for="m in g.members">{{m.name}} <strong>{{duration(m.seconds)}}</strong></p></div></article></div><p v-if="!groups.length" class="ft-empty">No groups here yet. Create one or explore Discover.</p></template><article v-else class="ft-panel ft-table-scroll"><table><thead><tr><th>Position</th><th>Member</th><th>Focus time</th></tr></thead><tbody><tr v-for="(person,index) in social.rankings" :class="{ 'ft-you':person.you}"><td>{{Number(index)+1}}</td><td>{{person.name}} {{person.you?'(You)':''}}</td><td>{{duration(person.seconds)}}</td></tr></tbody></table></article></template>
<template v-else-if="section==='Forest'"><article class="ft-forest ft-panel"><div class="ft-tree" aria-hidden="true">♧</div><p class="ft-eyebrow">YOUR FOCUS IS GROWING</p><h2>Level {{level}} · {{data.sunlight}}g sunlight</h2><p class="ft-muted">Every completed focus session helps your forest grow.</p><progress :value="data.sunlight%600" max="600"></progress><p>{{600-data.sunlight%600}}g to the next level</p><button class="ft-primary" :disabled="busy||!pending" @click="run(async()=>{await focusApi('collect','POST',{});await load();},'Sunlight collected.')">Collect {{pending}}g sunlight</button><p class="ft-muted">Daily visit: 30g · Consecutive-day visit: 6g · Completed focus: 1g per full minute.</p></article><article class="ft-panel"><h3>Sunlight activity</h3><div v-for="r in data.rewards.filter((r:any)=>r.grams>0).slice(0,30)" class="ft-report-row"><div>{{r.reason}}<small class="ft-muted">{{new Date(r.created_at).toLocaleString()}}</small></div><strong>+{{r.grams}}g {{r.collected_at?'collected':'available'}}</strong></div></article></template>
<FocusSettings v-else-if="section==='Settings'" :settings="data.settings" :busy="busy" @save="s=>run(async()=>{await focusApi('settings','POST',s);await load();},'Preferences saved.')" @clear="open('clear')"/>
</section></div>
<button v-if="active&&section!=='Timer'" class="ft-mini-timer" @click="select('Timer')"><span class="ft-mini-dot"></span><strong>{{clock}}</strong><span>{{active.task_title}} · {{active.status}}</span><small>Open timer →</small></button>
<dialog ref="dialog" class="ft-dialog" @cancel="close" @click="e=>{if(e.target===dialog)close();}"><template v-if="editor"><header class="ft-heading"><div><p class="ft-eyebrow">FOCUS TO DO</p><h2>{{kind==='task'?(editor.id?'Task details':'New task'):kind==='manual'?'Manual focus record':kind==='clear'?'Delete Focus data':kind==='group'?'Create a group':editor.id?'Edit '+kind:'New '+kind}}</h2></div><button type="button" aria-label="Close dialog" @click="close">×</button></header><form @submit.prevent="save"><div class="ft-dialog-body"><template v-if="kind==='task'"><label>Task name<input v-model="editor.title" maxlength="250" required autofocus></label><div class="ft-fields"><label>Project<select v-model="editor.project_id"><option :value="null">Tasks / inbox</option><option v-for="p in projects" :value="p.id">{{p.name}}</option></select></label><label>Priority<select v-model="editor.priority"><option v-for="p in ['none','low','medium','high']">{{p}}</option></select></label><label>Estimated focus sessions<input v-model.number="editor.estimate" type="number" min="0" max="999" required></label><label>Due date<input v-model="editor.due_date" type="date"></label><label>Reminder<input v-model="editor.remindLocal" type="datetime-local"></label><label>Repeat<select v-model="editor.repeat"><option v-for="p in ['none','daily','weekly','monthly','yearly']">{{p}}</option></select></label></div><label>Tags (comma separated)<input v-model="editor.tagText" placeholder="work, planning"></label><label>Notes<textarea v-model="editor.notes" rows="4" maxlength="15000"></textarea></label><div class="ft-heading"><h3>Subtasks</h3><button type="button" @click="editor.subtasks.push({title:'',done:false})">+ Add subtask</button></div><div v-for="(sub,index) in editor.subtasks" class="ft-subtask"><input v-model="sub.done" type="checkbox" aria-label="Subtask complete"><input v-model="sub.title" placeholder="Subtask" required maxlength="250"><button type="button" aria-label="Remove subtask" @click="editor.subtasks.splice(index,1)">×</button></div><p v-if="editor.completed_at" class="ft-muted">Completed {{new Date(editor.completed_at).toLocaleString()}}</p></template>
<template v-else-if="kind==='project'||kind==='folder'"><label>Name<input v-model="editor.name" maxlength="120" required></label><label>Colour<input v-model="editor.color" type="color"></label><label v-if="kind==='project'">Folder<select v-model="editor.folder_id"><option :value="null">No folder</option><option v-for="f in folders" :value="f.id">{{f.name}}</option></select></label></template>
<template v-else-if="kind==='manual'"><p class="ft-muted">Manual focus appears in your reports, but earns no sunlight or ranking credit.</p><label>Task<select v-model="editor.task_id" required><option v-for="t in data.tasks" :value="t.id">{{t.title}}</option></select></label><label>Started at<input v-model="editor.started_at" type="datetime-local" required></label><label>Minutes<input v-model.number="editor.minutes" type="number" min="1" max="1440" required></label><h3>Recent manual records</h3><button v-for="record in data.sessions.filter((s:any)=>s.manual).slice(0,10)" type="button" class="ft-manual-record" @click="open('manual',record)">{{record.task_title}} · {{duration(record.elapsed_seconds)}} · Edit</button></template>
<template v-else-if="kind==='group'"><label>Group name<input v-model="editor.name" maxlength="120" required></label><label>Description<textarea v-model="editor.description" maxlength="1000"></textarea></label></template>
<template v-else><p>This permanently deletes your Focus To Do data. Type <strong>DELETE MY FOCUS DATA</strong> to confirm.</p><input v-model="editor.confirmation" required pattern="DELETE MY FOCUS DATA" aria-label="Delete confirmation"></template><p v-if="error" class="ft-error" role="alert">{{error}}</p></div><footer class="ft-dialog-footer"><button v-if="editor.id&&kind==='task'" type="button" class="ft-danger" :disabled="busy" @click="removeTask">Delete task</button><button v-if="editor.id&&['project','folder'].includes(kind)" type="button" class="ft-danger" :disabled="busy" @click="removeProject">Delete {{kind}}</button><button type="button" @click="close">Cancel</button><button class="ft-primary" :disabled="busy">{{busy?'Saving…':kind==='clear'?'Delete my data':'Save changes'}}</button></footer></form></template></dialog>
</main></template>
